import react, { useEffect, useMemo, useReducer, useRef, useState } from 'react'
// 用于测试按键时的反应速度
// 倒计时出现色块，按下按键，统计倒计时到按下按键时候的各种数据
export default function TestKeyBoard() {

  const keysData = useRef<Record<string, {
    /** 对应的heighlightShowTime，用来标记它是什么时候出现的色块 */
    id: number,
    delay: number
  }[]>>({});
  //是否监听按键的开关
  const [times, setTimes] = useState(0);
  const [keyDown, setKeyDown] = useState('');
  const style = useState();
  // 第nextTestSetTime次测试的时候，色块出现高亮的时间戳，为0表示没有色块高亮
  const heighlightShowTimeRef = useRef(0);
  const [heighlightShowTime, setheighlightShowTime] = useState(0);

  const updateHeighlightShowTime = (t: number) => {
    setheighlightShowTime(t);
    heighlightShowTimeRef.current = t;
  }

  // 色块出现在哪个按键
  const [key, setKey] = useState('');

  /**  下一个任务出现的时间，nextTestSetTime + delay === heighlightShowTime */
  const nextTestSetTime = useRef(0);
  const nextTestSetTimeDelay = useRef(0)

  /** 倒计时delay（默认随机）后设置下一个按键高亮 */
  const nextTest = useMemo(() => function nextTest(delay = 0) {
    updateHeighlightShowTime(0);
    const delayTime = delay || Math.random() * 4000 + 1000 * 1;
    nextTestSetTime.current = Date.now();
    nextTestSetTimeDelay.current = delay;
    return setTimeout(() => {
      const t = new Date().getTime();
      // 倒计时后出现色块和设置出现高亮的按键
      updateHeighlightShowTime(t);
      setKey('');
    }, delayTime);
  }, [])

  // 监听按键按下事件：统计数据并设置下一次按键
  const listenKeyDown = useMemo(() => {
    return function listenKey(e: KeyboardEvent) {
      if (!heighlightShowTimeRef.current) {
        // 在没有色块的时候按下了按键
        console.log('===提前按')
        return;
      }
      const pressKey = e.code;
      if (key) {
        // TODO 区别按键
        return;
      }

      // 不区别按键，所有按键一视同仁
      setKeyDown(pressKey);
      if (!keysData.current[pressKey]) {
        keysData.current[pressKey] = []
      }
      const currentTime = new Date().getTime();
      const delay = currentTime - heighlightShowTimeRef.current;
      console.log('反应时间:', delay);
      keysData.current[pressKey].push({
        id: heighlightShowTimeRef.current,
        delay
      });
      nextTest();
      // if (delay < 2000) {
      //   ///只统计2秒以内的数据
      //   console.log('==push',delay)
      //   
      // }

    }
  }, [nextTest, key]);


  useEffect(() => {
    if (times) {
      keysData.current = {};
      document.addEventListener('keydown', listenKeyDown)
      return () => {
        document.removeEventListener('keydown', listenKeyDown);
      }
    }

  }, [times, listenKeyDown])

  console.log({ keysData })

  return <div>
    <p>测试按键反应速度</p>
    {times > 0 ? '正在测试中' : ''}
    <br></br>
    <button onClick={() => { setTimes(1); nextTest(5000) }}>开始</button>
    <button onClick={() => setTimes(0)}>结束</button>
    <div style={{
      height: '200px',
      width: '200px',
      display: times ? 'block' : 'none',
      background: heighlightShowTime ? 'green' : 'transparent',
      border: '5px solid'
    }}>
      当色块变色的时候按下某个按键
    </div>
    <br />
  </div>
}